sys_variable_value.value:
(function execute(inputs, outputs) {
    var session_details = JSON.parse(inputs.parameter);
    outputs.output_details = session_details;
    outputs.session_id=session_details.verification.id;
    outputs.url = session_details.verification.url;
    var gr = new GlideRecord('x_vuram_financia_0_fcc_kyc_entity_details');
    if (gr.get(inputs.sys_parm)) { 
        gr.video_kyc_link = session_details.verification.url;  
        gr.update();
    } else {
        gs.error('No record found with sys_id: ' + inputs.sys_parm);
    }
})(inputs, outputs);

